function openKpiForm(id=null){
 if(!canEdit()){toast("Tu rol no permite modificar KPI.","error");return}
 const k=state.kpis.find(x=>x.id===id)||{id:"",name:"",perspective:"financiera",objectiveId:"",unit:"%",formula:"",baseline:null,target:100,current:null,direction:"mayor",frequency:"Mensual",owner:currentUser.name,area:currentUser.area||"General",weight:1,alertAt:90,criticalAt:75,calculation:"excel",lower:0,upper:100,description:"",measurements:[]};const editing=!!id;
 const body=`<form id="kpiForm" class="detail-form-grid"><div class="field"><label for="kName">Nombre del indicador *</label><input id="kName" required value="${escapeHtml(k.name)}"></div>${selectField("Perspectiva","kPerspective",optionsPerspectives(k.perspective))}<div class="field full-span"><label for="kDescription">Descripción</label><textarea id="kDescription">${escapeHtml(k.description)}</textarea></div>${selectField("Objetivo asociado","kObjective",objectiveOptions(k.objectiveId))}${field("Unidad de medida","kUnit",k.unit,"text",true)}<div class="field full-span"><label for="kFormula">Fórmula de cálculo *</label><input id="kFormula" required value="${escapeHtml(k.formula)}"></div>${field("Línea base","kBaseline",k.baseline??"","number",false,'step="any"')}${field("Meta","kTarget",k.target,"number",true,'step="any"')}${field("Resultado actual","kCurrent",k.current??"","number",false,'step="any"')} ${selectField("Sentido del indicador","kDirection",`<option value="mayor" ${k.direction==="mayor"?"selected":""}>Mayor es mejor</option><option value="menor" ${k.direction==="menor"?"selected":""}>Menor es mejor</option><option value="rango" ${k.direction==="rango"?"selected":""}>Dentro de un rango</option>`)}${selectField("Frecuencia","kFrequency",["Mensual","Trimestral","Semestral","Anual"].map(x=>`<option ${k.frequency===x?"selected":""}>${x}</option>`).join(""))}${selectField("Responsable","kOwner",userOptions(k.owner))}${field("Área","kArea",k.area,"text",true)}${field("Peso del KPI","kWeight",k.weight,"number",true,'min="0" step="1"')}${field("Umbral verde / logrado (%)","kAlert",k.alertAt,"number",true,'min="0" max="100"')}${field("Umbral ámbar / en riesgo (%)","kCritical",k.criticalAt,"number",true,'min="0" max="100"')}<div class="field ${k.direction==="rango"?"":"hidden"}" id="rangeLowerWrap"><label for="kLower">Límite inferior</label><input id="kLower" type="number" step="any" value="${k.lower??0}"></div><div class="field ${k.direction==="rango"?"":"hidden"}" id="rangeUpperWrap"><label for="kUpper">Límite superior</label><input id="kUpper" type="number" step="any" value="${k.upper??100}"></div><div class="field full-span"><div class="info-box">Cumplimiento “mayor es mejor”: resultado ÷ meta × 100. “Menor es mejor”: meta ÷ resultado × 100. Se redondea a un decimal y no se limita al 100%. Como en el Excel, meta o resultado igual a cero no tiene cálculo. En rango: 100% dentro de límites y reducción proporcional fuera de ellos.</div></div></form>`;
 showModal(editing?"Editar indicador KPI":"Nuevo indicador KPI",body,editing?"Guardar cambios":"Crear indicador",()=>{
  if(!validateForm(["kName","kPerspective","kObjective","kUnit","kFormula","kTarget","kFrequency","kOwner","kArea","kWeight","kAlert","kCritical"]))return;
  const target=Number($("#kTarget").value),alertAt=Number($("#kAlert").value),criticalAt=Number($("#kCritical").value),direction=$("#kDirection").value;
  if(target===0&&direction==="menor"){toast("Para indicadores de menor es mejor, la meta debe ser distinta de cero.","error");return}
  if(alertAt<criticalAt||alertAt>100||criticalAt<0){toast("El umbral de alerta debe ser mayor o igual al umbral crítico.","error");return}
  const current=$("#kCurrent").value===""?null:Number($("#kCurrent").value);
  const payload={name:$("#kName").value.trim(),perspective:$("#kPerspective").value,objectiveId:$("#kObjective").value,description:$("#kDescription").value.trim(),unit:$("#kUnit").value.trim(),formula:$("#kFormula").value.trim(),baseline:$("#kBaseline").value===""?null:Number($("#kBaseline").value),calculation:"excel",target,current,direction,frequency:$("#kFrequency").value,owner:$("#kOwner").value,area:$("#kArea").value.trim(),weight:Number($("#kWeight").value),alertAt,criticalAt,lower:direction==="rango"?Number($("#kLower").value):null,upper:direction==="rango"?Number($("#kUpper").value):null};
  if(direction==="rango"&&payload.lower>payload.upper){toast("El límite inferior no puede superar el superior.","error");return}
  if(editing){if(k.current!==current){const period=[...k.measurements].sort((a,b)=>a.period.localeCompare(b.period)).at(-1)?.period||state.period;k.measurements.push({id:"M-"+k.id+"-"+Date.now(),period,date:today().startsWith(period)?today():"",value:current,notes:"Resultado actualizado desde la ficha del indicador.",responsible:payload.owner});}Object.assign(k,payload);recordAudit("Edición","KPI",`${k.id}: ${k.name}`)}else{const newid="KPI-"+String(Math.max(0,...state.kpis.map(x=>Number(x.id.split("-")[1])||0))+1).padStart(2,"0");state.kpis.push({id:newid,...payload,measurements:[]});recordAudit("Creación","KPI",`${newid}: ${payload.name}`)}
  saveState();closeModal();renderPage(currentPage);toast(editing?"Indicador actualizado":"Indicador creado");
 });
 $("#kDirection")?.addEventListener("change",()=>{$("#rangeLowerWrap")?.classList.toggle("hidden",$("#kDirection").value!=="rango");$("#rangeUpperWrap")?.classList.toggle("hidden",$("#kDirection").value!=="rango")});
}
function openMeasurementForm(measureId=null,kpiId=null){
 const k=state.kpis.find(x=>x.id===kpiId)||state.kpis[0];if(!k){toast("Primero crea un KPI.","error");return}
 let existing=null;if(measureId){for(const x of state.kpis){existing=x.measurements.find(m=>m.id===measureId);if(existing)break}}
 const chosen=existing?state.kpis.find(x=>x.measurements.includes(existing)):k;
 const m=existing||{period:state.period,date:today().startsWith(state.period)?today():"",value:"",notes:"",responsible:chosen.owner};
 const body=`<form id="measurementForm" class="detail-form-grid">${selectField("Indicador KPI","mKpi",state.kpis.map(x=>`<option value="${x.id}" ${x.id===chosen.id?"selected":""}>${escapeHtml(x.id+" · "+x.name)}</option>`).join(""))}${field("Período (AAAA o AAAA-MM)","mPeriod",m.period,"text",true)}${field("Fecha de medición","mDate",m.date,"date",false)}${field(`Valor obtenido (${escapeHtml(chosen.unit)})`,"mValue",m.value,"number",true,'step="any"')}${selectField("Responsable","mOwner",userOptions(m.responsible||chosen.owner))}<div class="field full-span"><label for="mNotes">Observaciones</label><textarea id="mNotes">${escapeHtml(m.notes)}</textarea></div><div class="field full-span"><div class="info-box">Al guardar, el sistema actualiza el valor actual del indicador si la medición corresponde al período más reciente o a un período posterior.</div></div></form>`;
 showModal(existing?"Editar medición":"Registrar resultado KPI",body,existing?"Guardar cambios":"Registrar medición",()=>{
  if(!validateForm(["mKpi","mPeriod","mValue","mOwner"]))return;
  const measurementPeriod=$("#mPeriod").value.trim(),measurementDate=$("#mDate").value;
  if(!/^20\d{2}(-(?:0[1-9]|1[0-2]))?$/.test(measurementPeriod)||!measurementPeriod.startsWith(state.period)){toast("Usa el año del BSC activo, solo o seguido de mes: "+state.period+" o "+state.period+"-06.","error");return}
  if(measurementDate&&!measurementDate.startsWith(measurementPeriod)){toast("La fecha debe corresponder al período de la medición.","error");return}
  const targetKpi=state.kpis.find(x=>x.id===$("#mKpi").value);const val=Number($("#mValue").value);if(!Number.isFinite(val)){toast("El resultado debe ser numérico.","error");return}
  const payload={period:measurementPeriod,date:measurementDate,value:val,notes:$("#mNotes").value.trim(),responsible:$("#mOwner").value};
  if(existing&&targetKpi===chosen){Object.assign(existing,payload)}else{if(existing){chosen.measurements=chosen.measurements.filter(x=>x.id!==existing.id)}const newid="M-"+targetKpi.id+"-"+Date.now();targetKpi.measurements.push({id:newid,...payload})}
  for(const item of new Set([chosen,targetKpi])){item.measurements.sort((a,b)=>a.period.localeCompare(b.period)||a.date.localeCompare(b.date));item.current=item.measurements.at(-1)?.value??null;}
  recordAudit(existing?"Edición":"Registro","Medición",`${targetKpi.id}: ${val} ${targetKpi.unit} (${payload.period})`);saveState();closeModal();renderPage(currentPage);toast(existing?"Medición actualizada":"Resultado registrado; dashboard y reportes actualizados");
 });
 $("#mKpi")?.addEventListener("change",()=>{const kk=state.kpis.find(x=>x.id===$("#mKpi").value);$("#mValue").parentElement.querySelector("label").textContent=`Valor obtenido (${kk.unit}) *`;$("#mOwner").value=kk.owner});
}
